__NUXT_JSONP__("/th/school-calendar", {data:[{details:{slug:"th",pageTitle:"MLI School Calendar | Mentor Language Institute",pageDescription:"The program strating date varies depending on F1 or Non F1 students.",title:"MLI School Calendar (2025-2026)",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003Eสีเหลือง\u003C\u002Ffont\u003E: วันที่เริ่มต้นโปรแกรม (โมดูล)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003Eเขียว\u003C\u002Ffont\u003E: ไม่มีโรงเรียน (วันหยุด)"],schoolCalendar:{title:"ปฏิทินโรงเรียน (วันที่เริ่มต้นโปรแกรม)",description:["วันที่จัดโปรแกรมจะแตกต่างกันไปขึ้นอยู่กับนักเรียน F1 หรือนักเรียนที่ไม่ใช่ F1"],lists:[{key:"นักเรียนที่ไม่ใช่ F1 ที่ไม่ได้รับวีซ่านักเรียน",value:["เริ่มโปรแกรมได้ทุกวันจันทร์ \u003Cbr\u003E หากวันจันทร์เป็นวันหยุด วันที่เริ่มต้นโปรแกรมจะเป็นวันอังคารของสัปดาห์นั้น"]},{key:"นักเรียน F1 ที่ได้รับวีซ่านักเรียน",value:["เริ่มได้ในวันจันทร์ที่กำหนด (เน้นสีเหลืองบนปฏิทิน)","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"คำถามที่พบบ่อยเกี่ยวกับวันที่เดินทางมาถึงสหรัฐอเมริกา",lists:[{key:"\u003Cb\u003Eกี่วันก่อนวันเริ่มต้นโปรแกรม นักเรียนสามารถเข้าประเทศสหรัฐอเมริกาได้?\u003C\u002Fb\u003E",value:["MLI ไม่ต้องการให้นักเรียนของเรามาที่สหรัฐอเมริกาล่วงหน้าตามจำนวนวันที่กำหนด \u003Cbr\u003E อย่างไรก็ตาม นักเรียนของเรามักจะเข้าประเทศสหรัฐอเมริกา 1 หรือ 2 วันก่อนวันเริ่มต้นโปรแกรม"],note:"หมายเหตุ: นักเรียนต่างชาติสามารถเข้าประเทศสหรัฐอเมริกาได้ 30 วันก่อนวันเริ่มต้นโปรแกรม"},{key:"\u003Cb\u003Eเป็นไปได้ไหมที่จะย้ายเข้าที่พักก่อนวันเริ่มต้นโปรแกรม?\u003C\u002Fb\u003E",value:["ใช่. เราสามารถจัดเตรียมที่พักของคุณที่จะย้ายเข้าวันที่ใดก็ได้ \u003Cbr\u003E  หากมีคำถามอื่น ๆ โปรดอย่าลังเลที่จะปรึกษาเรา"]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.896Z",updatedAt:"2026-04-24T11:47:24.351Z"}}],fetch:{},mutations:void 0});